# shellcheck shell=bash
# Shared helpers for the Orca "docker-devcontainer" environment recipe.
# Generated by the configure-devcontainer-environment skill (--enable-orca).
#
# Every workspace gets its own local Docker container, built from the
# devcontainer image plus an sshd layer (.devcontainer/orca/Dockerfile) and
# reached by Orca over SSH. .devcontainer/devcontainer.json stays the single
# source of truth: image/build/features, mounts, containerEnv, remoteEnv,
# runArgs, remoteUser and the lifecycle commands (initializeCommand,
# postCreateCommand, postStartCommand) are read from it.
#
# Mount translation (devcontainer -> Orca container), <HOME> = remoteUser's home:
#   */.vscode-server*                    dropped (editor only)
#   <HOME>/.codex, <HOME>/.codex/{.tmp,tmp} dropped (Codex state is container-owned)
#   <HOME>/.claude                       -> <HOME>/.claude-host   (credentials linked, state seeded)
#   <HOME>/.local/share/opencode         -> <HOME>/.opencode-host (credentials linked)
#   everything else                      unchanged
# plus a read-write bind of every worktree.sharedDirectories entry of orca.yaml
# (git-ignored working directories) into the container's primary checkout;
# Orca links them into each worktree it creates there.
# .devcontainer/link-agent-auth.sh links the credential files from the *-host
# mounts, so one login is shared without sharing caches or sqlite state.
# OpenCode v2 keeps its logins in SQLite instead; share_opencode_auth copies
# the host's (GitHub Copilot by default) with `opencode auth export | import`.
# share_credentials logs the container's gh in with the host's gh token; no
# SSH keys or other git credentials are copied.
#
# Host-side state (SSH key, known_hosts, locks) lives outside the repository in
# ORCA_DOCKER_STATE_DIR (default ~/.config/orca-docker/<repo>), so processes in
# the devcontainer, which bind-mounts the repository, cannot read the key.
#
# Written for macOS /bin/bash 3.2, Linux bash and Git Bash on Windows.
#
# Windows: Orca runs the recipe through cmd.exe, so orca.yaml calls
# "./scripts/orca-vm/recipe" <step>, which cmd.exe resolves to recipe.cmd and
# which starts these scripts with Git Bash (never WSL's bash.exe). docker, git,
# jq and Orca are native Windows programs there: every host path handed to
# them is a C:/... path (host_path), and MSYS argument conversion is turned off
# so container paths such as /workspaces/x reach docker unchanged.

# Single-quoted snippets run remotely or are jq programs and literal devcontainer variables.
# shellcheck disable=SC2016

IS_WINDOWS=false
case "$(uname -s 2>/dev/null)" in MINGW*|MSYS*|CYGWIN*) IS_WINDOWS=true ;; esac
if $IS_WINDOWS; then
    export MSYS_NO_PATHCONV=1 MSYS2_ARG_CONV_EXCL='*'
fi

# Prints a host path in the form native tools understand (C:/... on Windows).
host_path() {
    if $IS_WINDOWS && [ -n "$1" ]; then cygpath -m "$1"; else printf '%s' "$1"; fi
}

ORCA_VM_DIR="$(host_path "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)")"
REPO_ROOT="$(host_path "$(cd "${ORCA_VM_DIR}/../.." && pwd)")"
REPO_NAME="$(basename "$REPO_ROOT")"
DEVCONTAINER_DIR="${REPO_ROOT}/.devcontainer"
DEVCONTAINER_JSON="${DEVCONTAINER_DIR}/devcontainer.json"
ORCA_IMAGE_DIR="${DEVCONTAINER_DIR}/orca"
ORCA_YAML="${REPO_ROOT}/orca.yaml"
HOST_HOME="$(host_path "$HOME")"
STATE_DIR="${ORCA_DOCKER_STATE_DIR:-${XDG_CONFIG_HOME:-${HOST_HOME}/.config}/orca-docker/${REPO_NAME}}"
STATE_DIR="$(host_path "$STATE_DIR")"
SSH_KEY="$(host_path "${ORCA_DOCKER_SSH_KEY:-${STATE_DIR}/id_ed25519}")"
# Earlier location inside the repository (migrated by ensure_ssh_key).
LEGACY_SSH_KEY="${ORCA_VM_DIR}/.ssh/id_ed25519"
# The scripts' own SSH and git calls trust only this file. Orca reads the
# desktop's ~/.ssh/known_hosts, so every entry is recorded in both.
KNOWN_HOSTS="${STATE_DIR}/known_hosts"
USER_KNOWN_HOSTS="${HOST_HOME}/.ssh/known_hosts"
LOCK_DIR="${STATE_DIR}/locks"
# shellcheck disable=SC2034 # used by docker-create.sh
LABEL_RECIPE="org.orca.recipe"
LABEL_REPO="org.orca.repo"
LOOPBACK="127.0.0.1"

log() { echo ">>> $*" >&2; }
die() { echo "orca-docker: $*" >&2; exit 1; }

# Orca may start the recipe with a GUI-app PATH that lacks Homebrew/Colima or
# Docker Desktop.
_extra_path=(/opt/homebrew/bin /usr/local/bin)
if $IS_WINDOWS; then
    _extra_path+=("$(cygpath -u "${ProgramFiles:-C:\\Program Files}")/Docker/Docker/resources/bin")
fi
for _dir in "${_extra_path[@]}"; do
    case ":${PATH}:" in *":${_dir}:"*) ;; *) [ -d "$_dir" ] && PATH="${PATH}:${_dir}" ;; esac
done
export PATH

for _cmd in docker jq git ssh ssh-keygen; do
    if ! command -v "$_cmd" >/dev/null 2>&1; then
        case "${IS_WINDOWS}:${_cmd}" in
            true:jq) die "required command not found: jq (winget install jqlang.jq)" ;;
            true:docker) die "required command not found: docker (install and start Docker Desktop)" ;;
        esac
        die "required command not found: ${_cmd}"
    fi
done
if command -v sha256sum >/dev/null 2>&1; then
    sha256() { sha256sum "$@"; }
elif command -v shasum >/dev/null 2>&1; then
    sha256() { shasum -a 256 "$@"; }
else
    die "required command not found: sha256sum or shasum"
fi
# The Windows jq writes CRLF line endings, which `read` would keep as part of
# every value; -b (Windows builds only) makes it write LF.
if $IS_WINDOWS && printf '1' | command jq -b . >/dev/null 2>&1; then
    jq() { command jq -b "$@"; }
fi

# Prints a new temporary file path in host_path form.
host_mktemp() { host_path "$(mktemp "${TMPDIR:-/tmp}/$1.XXXXXX")"; }

# Optional, gitignored file for ${localEnv:...} values that the Orca app
# process does not inherit from the login shell (API keys, ...). It is
# sourced as shell code: keep it to KEY=value lines.
if [ -f "${ORCA_VM_DIR}/local.env" ] && [ "${ORCA_DOCKER_SKIP_LOCAL_ENV:-}" != 1 ]; then
    set -a
    # shellcheck disable=SC1091
    . "${ORCA_VM_DIR}/local.env"
    set +a
fi

# --- exit hooks and locks ------------------------------------------------------

# Commands run (each in a subshell) when the script exits; EXIT_RC holds the
# exit status. Held locks are released afterwards.
EXIT_HOOKS=()
LOCKS_HELD=()
EXIT_RC=0
on_exit() { EXIT_HOOKS+=("$1"); }

_orca_exit() {
    EXIT_RC=$?
    set +e
    local hook i
    for hook in ${EXIT_HOOKS[@]+"${EXIT_HOOKS[@]}"}; do
        (eval "$hook")
    done
    i=${#LOCKS_HELD[@]}
    while [ "$i" -gt 0 ]; do
        i=$((i - 1))
        rm -rf "${LOCK_DIR}/${LOCKS_HELD[$i]}.lock"
    done
    exit "$EXIT_RC"
}
trap _orca_exit EXIT

# Portable mutual exclusion (macOS has no flock): an atomic mkdir plus the
# holder's PID, so a lock left behind by a killed process is taken over.
# Do not call from a subshell: the lock would outlive it until the script ends.
lock_acquire() {
    local name="$1" timeout="${2:-600}" dir pid waited=0
    dir="${LOCK_DIR}/${name}.lock"
    mkdir -p "$LOCK_DIR"
    until mkdir "$dir" 2>/dev/null; do
        pid="$(cat "${dir}/pid" 2>/dev/null || true)"
        if [ -n "$pid" ] && ! kill -0 "$pid" 2>/dev/null; then
            log "taking over stale lock ${name} (pid ${pid} is gone)"
            rm -rf "$dir"
            continue
        fi
        [ "$waited" -lt "$timeout" ] || die "timed out after ${timeout}s waiting for lock ${name} (held by pid ${pid:-?})"
        [ "$waited" -gt 0 ] || log "waiting for lock ${name} (held by pid ${pid:-?})"
        sleep 1
        waited=$((waited + 1))
    done
    echo "$$" >"${dir}/pid"
    LOCKS_HELD+=("$name")
}

lock_release() {
    local name="$1" kept=() held
    rm -rf "${LOCK_DIR}/${name}.lock"
    for held in ${LOCKS_HELD[@]+"${LOCKS_HELD[@]}"}; do
        [ "$held" = "$name" ] || kept+=("$held")
    done
    LOCKS_HELD=(${kept[@]+"${kept[@]}"})
}

# --- devcontainer.json -------------------------------------------------------------

dc_json() {
    # devcontainer.json may be JSONC; drop full-line // comments before jq.
    sed -E 's#^[[:space:]]*//.*$##' "$DEVCONTAINER_JSON" | jq "$@"
}

dc_json -e 'type == "object"' >/dev/null 2>&1 \
    || die "cannot parse ${DEVCONTAINER_JSON}: only strict JSON plus full-line // comments is supported (no /* */ comments or trailing commas)"

CONTAINER_USER="$(dc_json -r '.remoteUser // .containerUser // "root"')"
[[ "$CONTAINER_USER" =~ ^[a-z_][a-z0-9_-]*$ ]] || die "unsupported remoteUser \"${CONTAINER_USER}\""
if [ "$CONTAINER_USER" = root ]; then CONTAINER_HOME=/root; else CONTAINER_HOME="/home/${CONTAINER_USER}"; fi
PROJECT_ROOT_IN_CONTAINER="$(dc_json -r '.workspaceFolder // empty')"
PROJECT_ROOT_IN_CONTAINER="${PROJECT_ROOT_IN_CONTAINER:-/workspaces/${REPO_NAME}}"

# Docker Compose devcontainers: image, mounts and environment come from the
# devcontainer's service in the merged compose configuration
# (`docker compose config`), including override files that initializeCommand
# generates. Only the service's build/image, volumes, environment,
# extra_hosts, cap_add, security_opt and privileged are applied.
COMPOSE_SERVICE=""
if dc_json -e 'has("dockerComposeFile")' >/dev/null; then
    COMPOSE_SERVICE="$(dc_json -r '.service // empty')"
    [ -n "$COMPOSE_SERVICE" ] || die "devcontainer.json has dockerComposeFile but no service"
fi
is_compose() { [ -n "$COMPOSE_SERVICE" ]; }

# Expands devcontainer variables: ${localEnv:VAR[:default]}, ${env:VAR},
# ${localWorkspaceFolder}, ${localWorkspaceFolderBasename},
# ${containerWorkspaceFolder}, ${containerWorkspaceFolderBasename}.
expand_vars() {
    local s="$1" out="" match inner name def val
    if $IS_WINDOWS; then
        # VS Code on Windows has no HOME, so "${localEnv:HOME}${localEnv:USERPROFILE}"
        # means the profile there; Git Bash sets both and would join them.
        local both='${localEnv:HOME}${localEnv:USERPROFILE}' profile='${localEnv:USERPROFILE}'
        s="${s//"$both"/$profile}"
    fi
    while [[ "$s" =~ \$\{([^}]*)\} ]]; do
        match="${BASH_REMATCH[0]}"
        inner="${BASH_REMATCH[1]}"
        case "$inner" in
            localEnv:*|env:*)
                name="${inner#*:}"
                def=""
                if [[ "$name" == *:* ]]; then
                    def="${name#*:}"
                    name="${name%%:*}"
                fi
                [[ "$name" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || die "invalid variable name in \${${inner}}"
                val="${!name:-$def}"
                ;;
            localWorkspaceFolder) val="$REPO_ROOT" ;;
            localWorkspaceFolderBasename) val="$REPO_NAME" ;;
            containerWorkspaceFolder) val="$PROJECT_ROOT_IN_CONTAINER" ;;
            containerWorkspaceFolderBasename) val="$(basename "$PROJECT_ROOT_IN_CONTAINER")" ;;
            *) die "unsupported devcontainer variable \${${inner}}" ;;
        esac
        out="${out}${s%%"$match"*}${val}"
        s="${s#*"$match"}"
    done
    printf '%s' "${out}${s}"
}

# workspaceFolder may use ${localWorkspaceFolderBasename} and the like.
case "$PROJECT_ROOT_IN_CONTAINER" in
    *containerWorkspaceFolder*) die "workspaceFolder cannot refer to \${containerWorkspaceFolder}" ;;
esac
PROJECT_ROOT_IN_CONTAINER="$(expand_vars "$PROJECT_ROOT_IN_CONTAINER")"

# Prints one --mount spec with its bind source in host_path form, or nothing
# (and a log line) when the bind source does not exist: Docker would refuse to
# start the container, and the devcontainer setups mount optional agent
# directories only when present as well.
host_mount() {
    local spec="$1" part out="" type="" src="" key
    local IFS=','
    for part in $spec; do
        key="${part%%=*}"
        case "$key" in
            type) type="${part#*=}" ;;
            source|src)
                src="${part#*=}"
                if $IS_WINDOWS; then
                    case "$src" in
                        [A-Za-z]:*|/[A-Za-z]|/[A-Za-z]/*) src="$(cygpath -m "$src")" ;;
                    esac
                fi
                part="${key}=${src}"
                ;;
        esac
        out="${out:+${out},}${part}"
    done
    if [ "${type:-bind}" = bind ] && [ -n "$src" ] && [ ! -e "$src" ]; then
        log "skipping mount of ${src} (not found on this host)"
        return 0
    fi
    printf '%s' "$out"
}

# Prints the Orca form of one expanded --mount spec, or nothing to drop it.
translate_mount() {
    local spec="$1" target new_target="" part out=""
    target="$(printf '%s\n' "$spec" | tr ',' '\n' | sed -n -E 's/^(target|destination|dst)=//p' | head -n 1)"
    case "$target" in
        # The repository is seeded from a git bundle, never bound from the host.
        "$PROJECT_ROOT_IN_CONTAINER"|"${PROJECT_ROOT_IN_CONTAINER}/") return 0 ;;
        */.vscode-server|*/.vscode-server/*) return 0 ;;
        "${CONTAINER_HOME}/.codex"|"${CONTAINER_HOME}/.codex/.tmp"|"${CONTAINER_HOME}/.codex/tmp") return 0 ;;
        "${CONTAINER_HOME}/.claude") new_target="${CONTAINER_HOME}/.claude-host" ;;
        "${CONTAINER_HOME}/.local/share/opencode") new_target="${CONTAINER_HOME}/.opencode-host" ;;
        *) printf '%s' "$spec"; return 0 ;;
    esac
    local IFS=','
    for part in $spec; do
        case "$part" in
            target=*|destination=*|dst=*) part="target=${new_target}" ;;
        esac
        out="${out:+${out},}${part}"
    done
    printf '%s' "$out"
}

# Prints the worktree.sharedDirectories entries of orca.yaml, one per line.
# Handles the plain block-list form only.
shared_dirs() {
    [ -f "$ORCA_YAML" ] || return 0
    awk '
        /^[[:space:]]*(#|$)/ { next }
        /^[^[:space:]]/ { top = $0; sub(/:.*/, "", top); in_list = 0; next }
        top == "worktree" && /^[[:space:]]+sharedDirectories:[[:space:]]*$/ { in_list = 1; next }
        in_list && /^[[:space:]]+-[[:space:]]+/ {
            v = $0
            sub(/^[[:space:]]+-[[:space:]]+/, "", v)
            sub(/[[:space:]]+#.*$/, "", v)
            sub(/[[:space:]]+$/, "", v)
            gsub(/^["\047]|["\047]$/, "", v)
            print v
            next
        }
        { in_list = 0 }
    ' "$ORCA_YAML"
}

# --- Docker Compose devcontainers ------------------------------------------------------

# Compose project name the Dev Containers extension uses (it names volumes
# that have no explicit name): the compose file's own name, else
# <workspace folder>_devcontainer.
compose_project() {
    if [ -n "${COMPOSE_PROJECT_NAME:-}" ]; then printf '%s' "$COMPOSE_PROJECT_NAME"; return 0; fi
    printf '%s_devcontainer' "$REPO_NAME" | tr '[:upper:]' '[:lower:]' | tr -cd 'a-z0-9_-'
}

# Prints the merged compose configuration as JSON. Files that do not exist yet
# (an override written by initializeCommand) are left out.
compose_json() {
    local file files=() project
    while IFS= read -r file; do
        [ -n "$file" ] || continue
        case "$file" in /*|[A-Za-z]:*) ;; *) file="${DEVCONTAINER_DIR}/${file}" ;; esac
        [ -f "$file" ] && files+=(-f "$(host_path "$file")")
    done < <(dc_json -r '.dockerComposeFile | if type == "array" then .[] else . end')
    [ ${#files[@]} -gt 0 ] || die "none of the dockerComposeFile entries exist"
    project="$(compose_project)"
    # A top-level `name:` in the compose files wins, as with Dev Containers.
    # Without one, compose names the project after the first file's folder.
    local named folder_default
    named="$(docker compose "${files[@]}" config --format json 2>/dev/null | jq -r '.name // empty')" || named=""
    folder_default="$(basename "$(dirname "${files[1]}")" | tr '[:upper:]' '[:lower:]' | tr -cd 'a-z0-9_-' | sed -E 's/^[^a-z0-9]+//')"
    [ -z "$named" ] || [ "$named" = "$folder_default" ] || [ -n "${COMPOSE_PROJECT_NAME:-}" ] || project="$named"
    docker compose -p "$project" "${files[@]}" config --format json
}

# Prints `docker run` arguments of the compose service, one per line.
compose_run_args() {
    local json
    json="$(compose_json)" || return 1
    printf '%s' "$json" | jq -r --arg svc "$COMPOSE_SERVICE" '
        .name as $project | (.volumes // {}) as $vols | .services[$svc] as $s
        | if $s == null then error("compose service \($svc) not found") else . end
        | (($s.volumes // [])[]
            | (if .read_only then ",readonly" else "" end) as $ro
            | if .type == "bind" then "--mount", "type=bind,source=\(.source),target=\(.target)\($ro)"
              elif .type == "volume" and .source then
                  ($vols[.source] // {}) as $v
                  | "--mount", "type=volume,source=\($v.name // ($project + "_" + .source)),target=\(.target)\($ro)"
              elif .type == "volume" then "--mount", "type=volume,target=\(.target)"
              elif .type == "tmpfs" then "--mount", "type=tmpfs,target=\(.target)"
              else empty end),
          (($s.environment // {}) | to_entries[] | select(.value != null) | "-e", "\(.key)=\(.value)"),
          (($s.extra_hosts // []) | if type == "object" then to_entries[] | "\(.key)=\(.value)" else .[] end | "--add-host=\(.)"),
          (($s.cap_add // [])[] | "--cap-add=\(.)"),
          (($s.security_opt // [])[] | "--security-opt=\(.)"),
          (if $s.privileged then "--privileged" else empty end)'
}

# Builds the `docker run` arguments from devcontainer.json into DOCKER_RUN_ARGS.
collect_run_args() {
    DOCKER_RUN_ARGS=()
    local raw spec key value dir pending=""
    if is_compose; then
        local compose_args
        compose_args="$(compose_run_args)" || die "cannot read the compose service ${COMPOSE_SERVICE}"
        while IFS= read -r raw; do
            if [ "$pending" = --mount ]; then
                spec="$(host_mount "$raw")"
                [ -n "$spec" ] && spec="$(translate_mount "$spec")"
                [ -n "$spec" ] && DOCKER_RUN_ARGS+=(--mount "$spec")
                pending=""
            elif [ "$pending" = -e ]; then
                DOCKER_RUN_ARGS+=(-e "$raw")
                pending=""
            elif [ "$raw" = --mount ] || [ "$raw" = -e ]; then
                pending="$raw"
            elif [ -n "$raw" ]; then
                DOCKER_RUN_ARGS+=("$raw")
            fi
        done <<<"$compose_args"
    fi
    while IFS= read -r raw; do
        [ -n "$raw" ] || continue
        spec="$(host_mount "$(expand_vars "$raw")")"
        [ -n "$spec" ] && spec="$(translate_mount "$spec")"
        [ -n "$spec" ] && DOCKER_RUN_ARGS+=(--mount "$spec")
    done < <(dc_json -r '.mounts[]? | if type == "string" then . else
        "type=\(.type),source=\(.source),target=\(.target)" end')
    while IFS=$'\t' read -r key value; do
        [ -n "$key" ] || continue
        DOCKER_RUN_ARGS+=(-e "${key}=$(expand_vars "$value")")
    done < <(dc_json -r '.containerEnv // {} | to_entries[] | "\(.key)\t\(.value)"')
    while IFS= read -r raw; do
        [ -n "$raw" ] && DOCKER_RUN_ARGS+=("$(expand_vars "$raw")")
    done < <(dc_json -r '.runArgs[]?')
    while IFS= read -r dir; do
        case "$dir" in
            ''|/*|*..*|*,*) log "skipping shared directory '${dir}' (must be a plain relative path)"; continue ;;
        esac
        # The trailing slash matches directory-only patterns (/dir/) as well,
        # even before the directory exists.
        if ! git -C "$REPO_ROOT" check-ignore -q "${dir}/"; then
            log "skipping shared directory '${dir}' (not git-ignored)"
            continue
        fi
        mkdir -p "${REPO_ROOT}/${dir}"
        DOCKER_RUN_ARGS+=(--mount "type=bind,source=${REPO_ROOT}/${dir},target=${PROJECT_ROOT_IN_CONTAINER}/${dir}")
    done < <(shared_dirs)
}

# remoteEnv as a sourceable file (may contain secrets; never passed to docker run).
remote_env_file_content() {
    local key value sq
    echo "# Generated from devcontainer.json remoteEnv by scripts/orca-vm. Do not edit."
    while IFS=$'\t' read -r key value; do
        [[ "$key" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || continue
        value="$(expand_vars "$value")"
        [ -n "$value" ] || continue
        sq="$(printf '%s' "$value" | sed "s/'/'\\\\''/g")"
        printf "export %s='%s'\n" "$key" "$sq"
    done < <(dc_json -r '.remoteEnv // {} | to_entries[] | "\(.key)\t\(.value)"')
}

# docker exec as the devcontainer's remoteUser.
cexec() { docker exec -u "$CONTAINER_USER" "$@"; }

# Prints the host's opencode binary, or fails when there is none.
host_opencode() {
    local bin
    for bin in "$(command -v opencode 2>/dev/null || true)" "${HOME}/.opencode/bin/opencode"; do
        [ -n "$bin" ] && [ -x "$bin" ] && { printf '%s' "$bin"; return 0; }
    done
    return 1
}

# Copies the host's OpenCode logins into the container. OpenCode v2 keeps
# credentials in its SQLite database, not in a file that can be linked, so
# they go through `opencode auth export | opencode auth import`.
# ORCA_DOCKER_OPENCODE_AUTH lists the integration IDs (space-separated,
# default github-copilot; "all" for every login; empty or "none" disables).
# Never fails the caller and never logs the secrets.
share_opencode_auth() {
    local name="$1" bin id creds rc
    local ids="${ORCA_DOCKER_OPENCODE_AUTH-github-copilot}"
    case " ${ids} " in *" none "*) return 0 ;; esac
    [ -n "${ids// /}" ] || return 0
    case " ${ids} " in *" all "*) ids="all" ;; esac
    if ! bin="$(host_opencode)"; then
        log "opencode auth: no opencode on the host, logins not shared"
        return 0
    fi
    for id in $ids; do
        if [ "$id" = all ]; then
            creds="$("$bin" auth export 2>/dev/null)" || creds=""
        else
            creds="$("$bin" auth export "$id" 2>/dev/null)" || creds=""
        fi
        if ! printf '%s' "$creds" | jq -e 'type == "array" and length > 0' >/dev/null 2>&1; then
            log "opencode auth: no ${id} login on the host (sign in with 'opencode auth login')"
            continue
        fi
        # The opencode add-on installs to ~/.opencode/bin, which a
        # non-interactive exec does not have on PATH.
        rc=0
        printf '%s' "$creds" | cexec -i "$name" sh -c \
            'b="$(command -v opencode 2>/dev/null || echo "$HOME/.opencode/bin/opencode")"; [ -x "$b" ] || exit 127; exec "$b" auth import' \
            >/dev/null 2>&1 || rc=$?
        case "$rc" in
            0) log "opencode auth: shared the host's ${id} login" ;;
            127) log "opencode auth: no opencode in the container, logins not shared"; break ;;
            *) log "opencode auth: importing the ${id} login failed (continuing)" ;;
        esac
    done
    creds=""
}

# --- git credentials -------------------------------------------------------------
#
# share_credentials runs on create, resume and every
# `docker-workspace.sh create`. It never fails the caller and never logs or
# stores a secret on the host side.
#
#   ORCA_DOCKER_GITHUB_AUTH  gh (default): log the container's gh in with the
#                            host's `gh auth token`, make gh the git credential
#                            helper and rewrite GitHub SSH remotes to HTTPS;
#                            none: leave the container's gh alone.
#
# SSH keys are deliberately never copied: agents run as root in the container,
# so a key there (or one unlocked in an ssh-agent there) is readable by them,
# and personal keys usually open far more than the repository's remote.

GITHUB_HOST=github.com

# Prints the host's gh binary, or fails when there is none.
host_gh() {
    local bin
    for bin in gh gh.exe; do
        command -v "$bin" >/dev/null 2>&1 && { command -v "$bin"; return 0; }
    done
    return 1
}

# Runs in the container as remoteUser; reads the token (or an empty line to
# revoke) on stdin. Exit codes: 0 logged in, 3 kept the container's own login,
# 4 nothing to revoke, 127 no gh.
# shellcheck disable=SC2016
_GH_CONTAINER_SCRIPT='
host=$1
command -v gh >/dev/null 2>&1 || exit 127
IFS= read -r token || token=""
state="$HOME/.config/orca-docker/github-token.sha256"
hash() { printf "%s" "$1" | sha256sum | cut -d" " -f1; }
key="url.https://${host}/.insteadOf"
current="$(gh auth token --hostname "$host" 2>/dev/null)" || current=""
ours=false
[ -n "$current" ] && [ -f "$state" ] && [ "$(hash "$current")" = "$(cat "$state")" ] && ours=true
if [ -z "$token" ]; then
    [ -f "$state" ] || exit 4
    if $ours; then gh auth logout --hostname "$host" >/dev/null 2>&1 || true; fi
    for p in "git@${host}:" "ssh://git@${host}/"; do
        git config --global --fixed-value --unset-all "$key" "$p" 2>/dev/null || true
    done
    rm -f "$state"
    exit 0
fi
if [ -n "$current" ] && [ "$current" != "$token" ] && ! $ours; then exit 3; fi
if [ "$current" != "$token" ]; then
    printf "%s\n" "$token" | gh auth login --hostname "$host" --git-protocol https --with-token || exit 1
fi
mkdir -p "${state%/*}"
(umask 077 && hash "$token" >"$state")
gh auth setup-git --hostname "$host" || exit 1
for p in "git@${host}:" "ssh://git@${host}/"; do
    git config --global --get-all "$key" 2>/dev/null | grep -qxF "$p" || git config --global --add "$key" "$p"
done
'

# Shares the host's gh login with the container (see above).
share_github_auth() {
    local name="$1" bin token="" rc=0
    case "${ORCA_DOCKER_GITHUB_AUTH-gh}" in
        gh) ;;
        ''|none) return 0 ;;
        *) log "github auth: unknown ORCA_DOCKER_GITHUB_AUTH '${ORCA_DOCKER_GITHUB_AUTH}' (gh or none), skipped"; return 0 ;;
    esac
    # Without a host gh the login state is unknown: leave the container as is.
    if ! bin="$(host_gh)"; then
        log "github auth: no gh on the host, login not shared"
        return 0
    fi
    token="$("$bin" auth token --hostname "$GITHUB_HOST" 2>/dev/null | tr -d '\r\n')" || token=""
    [[ "$token" =~ ^[A-Za-z0-9_]+$ ]] || token=""
    printf '%s\n' "$token" | cexec -i "$name" sh -c "$_GH_CONTAINER_SCRIPT" _ "$GITHUB_HOST" >/dev/null 2>&1 || rc=$?
    if [ -z "$token" ]; then
        case "$rc" in
            0) log "github auth: no gh login on the host any more, removed the shared login" ;;
            4|127) log "github auth: no gh login on the host (run 'gh auth login' there), not shared" ;;
            *) log "github auth: removing the earlier shared login failed (continuing)" ;;
        esac
        return 0
    fi
    token=""
    case "$rc" in
        0) log "github auth: shared the host's gh login; git uses HTTPS for ${GITHUB_HOST}" ;;
        3) log "github auth: kept the container's own gh login" ;;
        127) log "github auth: no gh in the container, login not shared" ;;
        *) log "github auth: gh auth login in the container failed (offline, expired or missing scopes?)" ;;
    esac
}

# Prints "host port" of an SSH remote URL (port empty for the default), or
# fails for other transports.
ssh_remote_host() {
    local url="$1" hp host port=""
    case "$url" in
        ssh://*)
            hp="${url#ssh://}"; hp="${hp#*@}"; hp="${hp%%/*}"
            host="${hp%%:*}"
            [ "$hp" = "$host" ] || port="${hp#*:}"
            ;;
        *://*) return 1 ;;
        *:*)
            hp="${url#*@}"; host="${hp%%:*}"
            ;;
        *) return 1 ;;
    esac
    [ -n "$host" ] || return 1
    printf '%s %s' "$host" "$port"
}

# Shares the host's git credentials and agent logins with a running container.
share_credentials() {
    share_github_auth "$1"
    share_opencode_auth "$1"
}

write_remote_env() {
    local name="$1"
    remote_env_file_content | cexec -i "$name" sh -c \
        'umask 077; mkdir -p "$HOME/.config/devcontainer"; cat >"$HOME/.config/devcontainer/remote-env.sh"'
}

# Runs a devcontainer lifecycle command (string, array or object form).
run_lifecycle() {
    local where="$1" key="$2" name="${3:-}" type cmd
    type="$(dc_json -r --arg k "$key" '.[$k] | type')"
    case "$type" in
        null) return 0 ;;
        string)
            cmd="$(dc_json -r --arg k "$key" '.[$k]')"
            _run_lifecycle_cmd "$where" "$name" bash -c "$cmd"
            ;;
        array)
            _run_lifecycle_argv "$where" "$name" "$(dc_json -c --arg k "$key" '.[$k]')"
            ;;
        object)
            local entry
            while IFS= read -r entry; do
                if [ "$(printf '%s' "$entry" | jq -r 'type')" = string ]; then
                    _run_lifecycle_cmd "$where" "$name" bash -c "$(printf '%s' "$entry" | jq -r .)"
                else
                    _run_lifecycle_argv "$where" "$name" "$entry"
                fi
            done < <(dc_json -c --arg k "$key" '.[$k][]')
            ;;
        *) die "unsupported ${key} type: ${type}" ;;
    esac
}

_run_lifecycle_argv() {
    local where="$1" name="$2" json="$3" arg
    local argv=()
    while IFS= read -r -d '' arg; do argv+=("$arg"); done < <(printf '%s' "$json" | jq -j '.[] | tostring + "\u0000"')
    _run_lifecycle_cmd "$where" "$name" "${argv[@]}"
}

_run_lifecycle_cmd() {
    local where="$1" name="$2"
    shift 2
    if [ "$where" = host ]; then
        (cd "$REPO_ROOT" && "$@") >&2
    else
        # Login shell so the generated container environment and remoteEnv apply.
        local quoted
        quoted="$(printf '%q ' "$@")"
        cexec -w "$PROJECT_ROOT_IN_CONTAINER" "$name" bash -lc "$quoted" >&2
    fi
}

# --- image -----------------------------------------------------------------------

sanitize_name() {
    printf '%s' "$1" | tr '[:upper:]' '[:lower:]' | tr -c 'a-z0-9_.-' '-' | sed -E 's/^[^a-z0-9]+//' | cut -c1-63
}

# Tag of the Orca image: a hash of the build-relevant devcontainer.json keys
# and every file under .devcontainer/ (lifecycle scripts included, so a change
# there produces a new, mostly cached build). Changes to a build context
# outside .devcontainer/ need ORCA_DOCKER_REBUILD=1.
image_tag() {
    local hash
    hash="$(
        {
            dc_json -cS '{image, build, dockerFile, context, features}'
            if is_compose; then compose_service_build_json; fi
            [ "${ORCA_DOCKER_SKIP_FEATURES:-}" != 1 ] || echo "skip-features"
            # .generated/ holds per-start output of initializeCommand.
            cd "$DEVCONTAINER_DIR" && find . -type f ! -name .DS_Store ! -name devcontainer.json ! -path './.generated/*' \
                | LC_ALL=C sort | while IFS= read -r f; do sha256 "$f"; done
        } | sha256 | cut -c1-12
    )"
    printf 'orca-devcontainer-%s:%s' "$(sanitize_name "$REPO_NAME")" "$hash"
}

# Prints {build, image} of the compose service.
compose_service_build_json() {
    compose_json | jq -cS --arg svc "$COMPOSE_SERVICE" '.services[$svc] | {build, image}'
}

# Builds the devcontainer image itself and prints its reference.
_build_base_image() {
    local tag="$1" image dockerfile context target arg
    local build_args=()
    if dc_json -e '(.features // {}) | length > 0' >/dev/null; then
        if [ "${ORCA_DOCKER_SKIP_FEATURES:-}" = 1 ]; then
            log "WARNING: building without the devcontainer.json features (ORCA_DOCKER_SKIP_FEATURES=1)"
        else
            command -v devcontainer >/dev/null 2>&1 \
                || die "devcontainer.json uses features; install the devcontainer CLI (npm install -g @devcontainers/cli), move them into the Dockerfile, or set ORCA_DOCKER_SKIP_FEATURES=1 (e.g. in scripts/orca-vm/local.env) to build without them"
            devcontainer build --workspace-folder "$REPO_ROOT" --image-name "$tag" >&2 || return 1
            printf '%s' "$tag"
            return 0
        fi
    fi
    if is_compose; then
        local svc
        svc="$(compose_service_build_json)" || die "cannot read the compose service ${COMPOSE_SERVICE}"
        if printf '%s' "$svc" | jq -e '.build == null' >/dev/null; then
            image="$(printf '%s' "$svc" | jq -r '.image // empty')"
            [ -n "$image" ] || die "compose service ${COMPOSE_SERVICE} has neither build nor image"
            printf '%s' "$image"
            return 0
        fi
        context="$(host_path "$(printf '%s' "$svc" | jq -r '.build.context // "."')")"
        dockerfile="$(printf '%s' "$svc" | jq -r '.build.dockerfile // "Dockerfile"')"
        case "$dockerfile" in /*|[A-Za-z]:*) ;; *) dockerfile="${context}/${dockerfile}" ;; esac
        target="$(printf '%s' "$svc" | jq -r '.build.target // empty')"
        while IFS= read -r arg; do
            [ -n "$arg" ] && build_args+=(--build-arg "$arg")
        done < <(printf '%s' "$svc" | jq -r '.build.args // {} | to_entries[] | select(.value != null) | "\(.key)=\(.value)"')
        docker build -f "$(host_path "$dockerfile")" ${target:+--target "$target"} -t "$tag" \
            ${build_args[@]+"${build_args[@]}"} "$context" >&2 || return 1
        printf '%s' "$tag"
        return 0
    fi
    image="$(dc_json -r '.image // empty')"
    if [ -n "$image" ]; then
        printf '%s' "$(expand_vars "$image")"
        return 0
    fi
    dockerfile="$(dc_json -r '.build.dockerfile // .dockerFile // empty')"
    [ -n "$dockerfile" ] || die "devcontainer.json has neither image nor build.dockerfile"
    dockerfile="${DEVCONTAINER_DIR}/$(expand_vars "$dockerfile")"
    context="${DEVCONTAINER_DIR}/$(expand_vars "$(dc_json -r '.build.context // .context // "."')")"
    target="$(dc_json -r '.build.target // empty')"
    while IFS= read -r arg; do
        [ -n "$arg" ] && build_args+=(--build-arg "$(expand_vars "$arg")")
    done < <(dc_json -r '.build.args // {} | to_entries[] | "\(.key)=\(.value)"')
    docker build -f "$dockerfile" ${target:+--target "$target"} -t "$tag" \
        ${build_args[@]+"${build_args[@]}"} "$context" >&2 || return 1
    printf '%s' "$tag"
}

# Sets IMAGE_TAG, building the devcontainer image plus the sshd layer if the
# tag does not exist yet. Concurrent callers wait for one build.
ensure_image() {
    local base
    IMAGE_TAG="$(image_tag)"
    if [ "${ORCA_DOCKER_REBUILD:-}" != 1 ] && docker image inspect "$IMAGE_TAG" >/dev/null 2>&1; then
        return 0
    fi
    lock_acquire image 7200
    if [ "${ORCA_DOCKER_REBUILD:-}" = 1 ] || ! docker image inspect "$IMAGE_TAG" >/dev/null 2>&1; then
        log "building image ${IMAGE_TAG}; the first build takes a while"
        # Command substitution does not inherit errexit: check explicitly.
        base="$(_build_base_image "${IMAGE_TAG}-base")" || die "building the devcontainer image failed"
        docker build --build-arg "BASE_IMAGE=${base}" -t "$IMAGE_TAG" "$ORCA_IMAGE_DIR" >&2
    fi
    lock_release image
}

# --- SSH -------------------------------------------------------------------------

ensure_state_dir() {
    mkdir -p "$STATE_DIR"
    chmod 700 "$STATE_DIR"
}

ensure_ssh_key() {
    ensure_state_dir
    [ -f "$SSH_KEY" ] && return 0
    mkdir -p "$(dirname "$SSH_KEY")"
    if [ -z "${ORCA_DOCKER_SSH_KEY:-}" ] && [ -f "$LEGACY_SSH_KEY" ] && [ ! -L "$LEGACY_SSH_KEY" ]; then
        # Existing containers authorize this key and existing Orca SSH targets
        # point at the old path: move it and leave symlinks behind. The links
        # dangle inside the devcontainer, so the key stays unreadable there.
        mv "$LEGACY_SSH_KEY" "$SSH_KEY"
        if [ -f "${LEGACY_SSH_KEY}.pub" ]; then
            mv "${LEGACY_SSH_KEY}.pub" "${SSH_KEY}.pub"
        else
            ssh-keygen -y -f "$SSH_KEY" >"${SSH_KEY}.pub"
        fi
        ln -s "$SSH_KEY" "$LEGACY_SSH_KEY"
        ln -s "${SSH_KEY}.pub" "${LEGACY_SSH_KEY}.pub"
        log "moved SSH key ${LEGACY_SSH_KEY} to ${SSH_KEY}"
        return 0
    fi
    ssh-keygen -q -t ed25519 -N '' -C "orca-docker-${REPO_NAME}" -f "$SSH_KEY"
    log "generated SSH key ${SSH_KEY}"
}

ssh_opts() {
    printf '%s\n' -i "$SSH_KEY" -o IdentitiesOnly=yes -o BatchMode=yes \
        -o StrictHostKeyChecking=yes -o "UserKnownHostsFile=${KNOWN_HOSTS}" -o ConnectTimeout=5
}

container_running() { [ "$(docker inspect -f '{{.State.Running}}' "$1" 2>/dev/null)" = true ]; }

assert_running() {
    local name="$1"
    if ! container_running "$name"; then
        docker logs --tail 50 "$name" >&2 2>&1 || true
        die "container ${name} is not running"
    fi
}

# Prints the published loopback port of the container's sshd.
wait_for_port() {
    local name="$1" port="" _i
    for _i in $(seq 1 60); do
        assert_running "$name"
        port="$(docker port "$name" 22/tcp 2>/dev/null | awk -F: -v lo="$LOOPBACK" '$1 == lo { print $2; exit }')"
        [ -n "$port" ] && { printf '%s' "$port"; return 0; }
        sleep 1
    done
    die "no published SSH port for ${name}"
}

# Prints the container's ed25519 host public key ("type base64"), read through
# trusted local docker access.
read_host_key() {
    local name="$1" key="" _i
    for _i in $(seq 1 60); do
        assert_running "$name"
        key="$(docker exec "$name" cat /etc/ssh/ssh_host_ed25519_key.pub 2>/dev/null | awk '{print $1" "$2}')"
        [ -n "$key" ] && { printf '%s' "$key"; return 0; }
        sleep 1
    done
    die "container ${name} has no SSH host key"
}

# Removes an endpoint's entries from a known_hosts file (hashed ones too)
# without clobbering an existing <file>.old backup of the user.
_known_hosts_remove() {
    local file="$1" endpoint="$2" backup=""
    [ -f "$file" ] || return 0
    ssh-keygen -F "$endpoint" -f "$file" >/dev/null 2>&1 || return 0
    if [ -e "${file}.old" ]; then
        backup="$(mktemp "${file}.old.XXXXXX")"
        cp -p "${file}.old" "$backup"
    fi
    ssh-keygen -R "$endpoint" -f "$file" >/dev/null 2>&1 || true
    if [ -n "$backup" ]; then
        mv -f "$backup" "${file}.old"
    else
        rm -f "${file}.old"
    fi
}

# Replaces only this endpoint's entry with the verified key, in the scripts'
# known_hosts and in the desktop's (read by Orca).
record_known_host() {
    local port="$1" key="$2" endpoint="[${LOOPBACK}]:$1" file
    ensure_state_dir
    mkdir -p "$(dirname "$USER_KNOWN_HOSTS")"
    lock_acquire known_hosts 120
    for file in "$KNOWN_HOSTS" "$USER_KNOWN_HOSTS"; do
        touch "$file"
        if ! ssh-keygen -F "$endpoint" -f "$file" 2>/dev/null | grep -v '^#' | grep -qF " ${key}"; then
            _known_hosts_remove "$file" "$endpoint"
            printf '%s %s\n' "$endpoint" "$key" >>"$file"
        fi
    done
    lock_release known_hosts
}

# Removes the endpoint's entry only while it still holds the given key.
forget_known_host() {
    local port="$1" key="$2" endpoint="[${LOOPBACK}]:$1" file
    [ -n "$port" ] && [ -n "$key" ] || return 0
    lock_acquire known_hosts 120
    for file in "$KNOWN_HOSTS" "$USER_KNOWN_HOSTS"; do
        [ -f "$file" ] || continue
        if ssh-keygen -F "$endpoint" -f "$file" 2>/dev/null | grep -qF "$key"; then
            _known_hosts_remove "$file" "$endpoint"
        fi
    done
    lock_release known_hosts
}

wait_for_ssh() {
    local port="$1" _i _o opts=()
    while IFS= read -r _o; do opts+=("$_o"); done < <(ssh_opts)
    for _i in $(seq 1 30); do
        ssh "${opts[@]}" -p "$port" "${CONTAINER_USER}@${LOOPBACK}" true 2>/dev/null && return 0
        sleep 1
    done
    ssh "${opts[@]}" -p "$port" "${CONTAINER_USER}@${LOOPBACK}" true >&2 || die "SSH to ${LOOPBACK}:${port} failed"
}

# Verifies and records the host key of a running container, waits for its
# sshd and sets BROUGHT_UP_PORT and BROUGHT_UP_HOST_KEY.
#
# The explicit `|| return 1` keep failures fatal where callers disable errexit
# (`if`, `||`).
trust_container() {
    local name="$1"
    BROUGHT_UP_PORT="$(wait_for_port "$name")" || return 1
    BROUGHT_UP_HOST_KEY="$(read_host_key "$name")" || return 1
    record_known_host "$BROUGHT_UP_PORT" "$BROUGHT_UP_HOST_KEY" || return 1
    wait_for_ssh "$BROUGHT_UP_PORT"
}

# Prepares a (re)started container for SSH sessions and sets BROUGHT_UP_*.
bring_up() {
    local name="$1"
    trust_container "$name" || return 1
    write_remote_env "$name"
}

# Starts the container if needed, then bring_up.
start_container() {
    local name="$1"
    container_running "$name" || docker start "$name" >/dev/null || return 1
    bring_up "$name"
}

# --- repository ----------------------------------------------------------------

# Writes a bundle with every local branch, tag and origin/* ref plus HEAD
# (which may be detached). Fetched refs/remotes/orca/* are left out.
create_repo_bundle() {
    git -C "$REPO_ROOT" bundle create --quiet "$1" HEAD --branches --tags --remotes=origin
}

# Prints a remote URL without credentials, or fails when it is not an allowed
# form; credentials never travel into the containers in the remote URL (git
# credentials, if any, come from the devcontainer's own mounts). Allowed:
#   https://, http://, git://  userinfo (tokens such as
#                              https://x-access-token:ghp_...@host/...),
#                              query string and fragment are removed
#   ssh://[user@]host[:port]/  a password after the user is removed
#   [user@]host:path           scp-like SSH form
# Rejected: other transports (file://, ext::, fd::, local paths), control
# characters or whitespace, hosts starting with "-" and malformed hosts/ports.
sanitize_remote_url() {
    local url="$1" scheme authority rest host user=""
    local user_re='^[A-Za-z0-9._-]+$'
    local host_re='^([A-Za-z0-9][A-Za-z0-9.-]*|\[[0-9A-Fa-f:.]+\])(:[0-9]{1,5})?$'
    local url_re='^(https?|git|ssh)://([^/?#]*)(.*)$'
    local scp_re='^(([^@/:]+)@)?([A-Za-z0-9][A-Za-z0-9.-]*):(.+)$'
    case "$url" in ''|*[[:space:][:cntrl:]]*) return 1 ;; esac
    if [[ "$url" =~ $url_re ]]; then
        scheme="${BASH_REMATCH[1]}" authority="${BASH_REMATCH[2]}" rest="${BASH_REMATCH[3]}"
        host="${authority##*@}"
        [ "$host" = "$authority" ] || user="${authority%@*}"
        [[ "$host" =~ $host_re ]] || return 1
        case "$scheme" in
            ssh)
                user="${user%%:*}"
                if [ -n "$user" ]; then
                    [[ "$user" =~ $user_re ]] || return 1
                    host="${user}@${host}"
                fi
                ;;
            *)
                rest="${rest%%#*}"
                rest="${rest%%\?*}"
                ;;
        esac
        printf '%s://%s%s' "$scheme" "$host" "$rest"
        return 0
    fi
    case "$url" in *://*|*::*|/*|.*|-*) return 1 ;; esac
    if [[ "$url" =~ $scp_re ]]; then
        user="${BASH_REMATCH[2]}" host="${BASH_REMATCH[3]}" rest="${BASH_REMATCH[4]}"
        # "user:secret@host:path" would otherwise pass as host "user".
        case "${rest%%/*}" in *@*) return 1 ;; esac
        if [ -n "$user" ]; then
            [[ "$user" =~ $user_re ]] || return 1
            host="${user}@${host}"
        fi
        printf '%s:%s' "$host" "$rest"
        return 0
    fi
    return 1
}

# Prints the number of linked worktrees in the container's repository.
container_worktree_count() {
    cexec "$1" git -C "$PROJECT_ROOT_IN_CONTAINER" worktree list --porcelain \
        | awk '/^worktree / { n++ } END { print (n > 0 ? n - 1 : 0) }'
}

# Fetches the container's branches to the host (see docker-fetch.sh), starting
# a stopped container first. Runs in a subshell so a failure only returns 1.
fetch_container_branches() {
    (start_container "$1" && "${ORCA_VM_DIR}/docker-fetch.sh" "$1")
}

# Saves the container's branches when docker-fetch.sh fails, without SSH: a
# bundle made with docker exec or, if the container does not start, a copy of
# its .git directory. Prints the path; recover with
# git fetch <path> 'refs/heads/*:refs/remotes/orca/<container>/*'.
rescue_container_branches() {
    local name="$1" dest
    dest="${STATE_DIR}/rescue/${name}-$(date +%Y%m%d-%H%M%S)"
    (umask 077 && mkdir -p "${STATE_DIR}/rescue") || return 1
    if { container_running "$name" || docker start "$name" >/dev/null 2>&1; } \
        && cexec "$name" git -C "$PROJECT_ROOT_IN_CONTAINER" bundle create --quiet /tmp/orca-rescue.bundle --branches >&2 \
        && docker cp "${name}:/tmp/orca-rescue.bundle" "${dest}.bundle" >/dev/null 2>&1; then
        printf '%s' "${dest}.bundle"
    elif docker cp "${name}:${PROJECT_ROOT_IN_CONTAINER}/.git" "${dest}.git" >/dev/null 2>&1; then
        printf '%s' "${dest}.git"
    else
        rm -rf "${dest}.bundle" "${dest}.git"
        return 1
    fi
}

# --- recipe results --------------------------------------------------------------

emit_result() {
    local name="$1" port="$2" image="$3" host_key="$4"
    jq -n \
        --arg root "$PROJECT_ROOT_IN_CONTAINER" \
        --arg label "$name" \
        --arg host "$LOOPBACK" \
        --argjson port "$port" \
        --arg user "$CONTAINER_USER" \
        --arg key "$SSH_KEY" \
        --arg name "$name" \
        --arg image "$image" \
        --arg hostKey "$host_key" \
        '{
            schemaVersion: 1,
            connection: {
                type: "ssh",
                projectRoot: $root,
                target: {
                    label: $label, host: $host, port: $port, username: $user,
                    identityFile: $key, identitiesOnly: true
                }
            },
            userData: { provider: "docker", resourceId: $name, image: $image, hostKey: $hostKey }
        }'
}

# Reads the lifecycle payload (stdin) and validates that the resource is ours.
read_payload() {
    PAYLOAD="$(cat)"
    RESOURCE_ID="$(printf '%s' "$PAYLOAD" | jq -r '.recipeResult.userData.resourceId // empty')"
    [ -n "$RESOURCE_ID" ] || die "no recipeResult.userData.resourceId in lifecycle payload"
    # shellcheck disable=SC2034 # read by the sourcing scripts
    PAYLOAD_IMAGE="$(printf '%s' "$PAYLOAD" | jq -r '.recipeResult.userData.image // empty')"
    # shellcheck disable=SC2034
    PAYLOAD_HOST_KEY="$(printf '%s' "$PAYLOAD" | jq -r '.recipeResult.userData.hostKey // empty')"
    # shellcheck disable=SC2034
    PAYLOAD_PORT="$(printf '%s' "$PAYLOAD" | jq -r '.recipeResult.connection.target.port // empty')"
}

container_exists() { docker inspect "$1" >/dev/null 2>&1; }

assert_owned() {
    local name="$1" repo
    repo="$(docker inspect -f "{{index .Config.Labels \"${LABEL_REPO}\"}}" "$name" 2>/dev/null || true)"
    [ "$repo" = "$REPO_ROOT" ] || die "container ${name} was not created by this recipe for ${REPO_ROOT}"
}
